"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { FOCUSABLE_CHROME } from "@/lib/a11y";
import { PRIMARY_NAV } from "@/lib/nav";
import { site } from "@/lib/site";
import { ThemeToggle } from "@/components/theme-toggle";

export function SiteHeader() {
  const pathname = usePathname();

  return (
    <header className="sticky top-0 z-20 border-b border-border bg-background/80 backdrop-blur-xl backdrop-saturate-150">
      <div className="container-wide flex h-[52px] items-center justify-between gap-4 sm:h-14">
        <Link
          href="/"
          className="group flex min-h-9 items-center gap-2.5 no-underline"
        >
          <span
            aria-hidden
            className="relative flex size-[18px] items-center justify-center"
          >
            <span className="absolute inset-0 rounded-[4px] bg-foreground transition-transform duration-200 ease-[var(--ease-out-expo)] group-hover:scale-90" />
            <span className="relative size-[7px] rounded-[1px] bg-background" />
          </span>
          <span className="text-[13px] font-medium tracking-[-0.01em] text-foreground transition-opacity duration-150 group-hover:opacity-70">
            {site.handle}
          </span>
        </Link>

        <div className="flex items-center gap-1 sm:gap-1.5">
          <nav
            aria-label={FOCUSABLE_CHROME.primaryNavLabel}
            className="flex items-center"
          >
            {PRIMARY_NAV.map((item) => {
              const active =
                item.href === "/"
                  ? pathname === "/"
                  : pathname.startsWith(item.href);

              return (
                <Link
                  key={item.href}
                  href={item.href}
                  aria-current={active ? "page" : undefined}
                  className={[
                    "relative inline-flex min-h-9 items-center px-2.5 text-[13px] no-underline transition-colors duration-150 ease-[var(--ease-out-quad)] sm:px-3",
                    active
                      ? "font-medium text-foreground"
                      : "text-muted hover:text-foreground",
                  ].join(" ")}
                >
                  {item.label}
                  <span
                    aria-hidden
                    className={[
                      "pointer-events-none absolute inset-x-2.5 -bottom-px h-px bg-foreground transition-opacity duration-200 ease-[var(--ease-out-expo)] sm:inset-x-3",
                      active ? "opacity-100" : "opacity-0",
                    ].join(" ")}
                  />
                </Link>
              );
            })}
          </nav>
          <div className="ml-1 h-4 w-px bg-border" aria-hidden />
          <ThemeToggle />
        </div>
      </div>
    </header>
  );
}

"use client";

import { useSyncExternalStore } from "react";
import { useTheme } from "next-themes";
import { Moon, Sun } from "@phosphor-icons/react";

const emptySubscribe = () => () => {};

/** Quiet Vercel-like theme control — system default, persisted light/dark override. */
export function ThemeToggle() {
  const { resolvedTheme, setTheme } = useTheme();
  const mounted = useSyncExternalStore(emptySubscribe, () => true, () => false);
  const isDark = resolvedTheme === "dark";

  return (
    <button
      type="button"
      disabled={!mounted}
      className="inline-flex size-8 items-center justify-center rounded-md text-muted transition-[color,background-color,transform] duration-150 ease-[var(--ease-out-quad)] hover:bg-surface-hover hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-foreground active:scale-[0.94] disabled:pointer-events-none"
      aria-label={
        !mounted
          ? "Theme"
          : isDark
            ? "Switch to light theme"
            : "Switch to dark theme"
      }
      onClick={() => {
        if (!mounted) return;
        setTheme(isDark ? "light" : "dark");
      }}
    >
      <span className="relative size-4">
        {mounted ? (
          <>
            <Sun
              size={16}
              weight="bold"
              aria-hidden
              className={[
                "absolute inset-0 transition-[opacity,transform] duration-200 ease-[var(--ease-out-expo)]",
                isDark
                  ? "rotate-0 scale-100 opacity-100"
                  : "-rotate-90 scale-50 opacity-0",
              ].join(" ")}
            />
            <Moon
              size={16}
              weight="bold"
              aria-hidden
              className={[
                "absolute inset-0 transition-[opacity,transform] duration-200 ease-[var(--ease-out-expo)]",
                isDark
                  ? "rotate-90 scale-50 opacity-0"
                  : "rotate-0 scale-100 opacity-100",
              ].join(" ")}
            />
          </>
        ) : (
          <span className="absolute inset-0 rounded-sm bg-border" aria-hidden />
        )}
      </span>
    </button>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import { site } from "@/lib/site";

export function HomeIntro() {
  const reduce = useReducedMotion();

  return (
    <motion.section
      aria-labelledby="home-intro-heading"
      className="pt-14 pb-12 sm:pt-[4.5rem] sm:pb-14"
      initial={reduce ? false : { opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.45, ease: [0.16, 1, 0.3, 1] }}
    >
      <p className="meta-copy mb-4">Portfolio</p>
      <h1 id="home-intro-heading" className="display-title">
        {site.name}
      </h1>
      <p className="body-copy mt-5 max-w-[36rem]">{site.positioning}</p>
      <ul className="mt-7 flex flex-wrap items-center gap-x-1 gap-y-2 text-[13px]">
        {site.socials.map((social, index) => (
          <li key={social.label} className="flex items-center">
            {index > 0 ? (
              <span className="mx-2.5 text-border-strong" aria-hidden>
                /
              </span>
            ) : null}
            <a
              href={social.href}
              {...(social.href.startsWith("mailto:")
                ? {}
                : { target: "_blank", rel: "noopener noreferrer" })}
              className="link-editorial min-h-8 font-medium"
            >
              {social.label}
            </a>
          </li>
        ))}
      </ul>
    </motion.section>
  );
}

