export function tryParsePostSource(
  slug: string,
  fileContent: string,
): PostRecord | null {
  let fields: Record<string, string>;
  let content: string;
  try {
    ({ fields, content } = parseFrontmatterFields(slug, fileContent));
  } catch (error) {
    // WIP drafts with unsupported YAML must not break Home / RSS / sitemap.
    if (/\bdraft:\s*(true|yes|on|1)\b/i.test(fileContent)) {
      return null;
    }
    throw error;
  }

  const title = fields.title;
  const publishedAt = fields.publishedAt;
  const summary = fields.summary;
  const draft = parseBool(fields.draft);

  if (!title || !publishedAt || !summary) {
    if (draft) return null;
    throw new Error(
      `Post "${slug}" requires title, publishedAt, and summary frontmatter`,
    );
  }

  return {
    slug,
    title,
    publishedAt,
    summary,
    tags: parseTags(fields.tags),
    draft,
    image: fields.image,
    content,
    readingTimeMinutes: estimateReadingTimeMinutes(content),
  };
}

