 */
export type AiActivityPayload = {
  version: 1;
  generatedAt: string;
  timezone: string;
  /** Complete days only (through yesterday in `timezone`). */
  days: { date: string; tokens: number }[];
  lifetimeTokens: number;
};

export const AI_ACTIVITY_TIMEZONE = "Asia/Kolkata";
export const AI_ACTIVITY_BLOB_PATH = "ai-activity/latest.json";

export function isAiActivityPayload(value: unknown): value is AiActivityPayload {
  if (!value || typeof value !== "object") return false;
  const v = value as Record<string, unknown>;
  if (v.version !== 1) return false;
  if (typeof v.generatedAt !== "string") return false;
  if (typeof v.timezone !== "string") return false;
  if (typeof v.lifetimeTokens !== "number" || !Number.isFinite(v.lifetimeTokens)) {
    return false;
  }
  if (!Array.isArray(v.days)) return false;
  return v.days.every(
    (day) =>
      day &&
      typeof day === "object" &&
      typeof (day as { date?: unknown }).date === "string" &&
      /^\d{4}-\d{2}-\d{2}$/.test((day as { date: string }).date) &&
      typeof (day as { tokens?: unknown }).tokens === "number" &&
      Number.isFinite((day as { tokens: number }).tokens) &&
      (day as { tokens: number }).tokens >= 0,
  );
}

/** Calendar YYYY-MM-DD in a timezone. */
export function calendarDateInTimeZone(date: Date, timeZone: string): string {
  return new Intl.DateTimeFormat("en-CA", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(date);
}

/** Previous calendar day (YYYY-MM-DD) in a timezone. */
export function yesterdayInTimeZone(now: Date, timeZone: string): string {
  // Noon UTC probe days avoid DST edge cases when shifting by 24h from local midnight.
  const today = calendarDateInTimeZone(now, timeZone);
  const [y, m, d] = today.split("-").map(Number);
  const utcNoon = new Date(Date.UTC(y!, m! - 1, d!, 12, 0, 0));
  utcNoon.setUTCDate(utcNoon.getUTCDate() - 1);
  return calendarDateInTimeZone(utcNoon, timeZone);
}

/**
 * Fraction of the local calendar day elapsed [0, 1].
 */
export function dayFractionElapsed(now: Date, timeZone: string): number {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hour: "numeric",
    minute: "numeric",
    second: "numeric",
    hourCycle: "h23",
  }).formatToParts(now);
  const hour = Number(parts.find((p) => p.type === "hour")?.value ?? 0);
  const minute = Number(parts.find((p) => p.type === "minute")?.value ?? 0);
  const second = Number(parts.find((p) => p.type === "second")?.value ?? 0);
  const elapsed = hour * 3600 + minute * 60 + second;
  return Math.min(1, Math.max(0, elapsed / 86_400));
}

/**
 * Conservative full-day baseline: minimum of the last up-to-7 days
 * before `beforeDate` that have tokens > 0.
 */
export function sevenDayMinBaseline(
  days: readonly { date: string; tokens: number }[],
  beforeDate: string,
): number {
  const prior = days
    .filter((d) => d.date < beforeDate && d.tokens > 0)
    .sort((a, b) => a.date.localeCompare(b.date))
    .slice(-7);
  if (prior.length === 0) return 0;
  return Math.min(...prior.map((d) => d.tokens));
}

/** Projected tokens “so far today” from the 7-day min baseline. */
export function projectTodayTokens(
  days: readonly { date: string; tokens: number }[],
  now: Date,
  timeZone: string,
): { date: string; tokens: number; baseline: number } {
  const today = calendarDateInTimeZone(now, timeZone);
  const baseline = sevenDayMinBaseline(days, today);
  const tokens = Math.round(baseline * dayFractionElapsed(now, timeZone));
  return { date: today, tokens, baseline };
}

import { put } from "@vercel/blob";
import {
  AI_ACTIVITY_BLOB_PATH,
  type AiActivityPayload,
  isAiActivityPayload,
} from "@/lib/ai-activity-payload";

export async function publishAiActivityPayload(
  payload: AiActivityPayload,
): Promise<{ url: string }> {
  if (!isAiActivityPayload(payload)) {
    throw new Error("Invalid AI Activity payload");
  }
  const token = process.env.BLOB_READ_WRITE_TOKEN;
  if (!token) {
    throw new Error("BLOB_READ_WRITE_TOKEN is not configured");
  }

  const blob = await put(AI_ACTIVITY_BLOB_PATH, JSON.stringify(payload), {
    access: "public",
    addRandomSuffix: false,
    allowOverwrite: true,
    contentType: "application/json",
    token,
    // Visitors can reuse for up to an hour; nightly overwrite still replaces content.
    cacheControlMaxAge: 3600,
  });

  return { url: blob.url };
}

export async function fetchPublishedAiActivityPayload(): Promise<AiActivityPayload | null> {
  const url =
    process.env.AI_ACTIVITY_BLOB_URL ??
    process.env.NEXT_PUBLIC_AI_ACTIVITY_BLOB_URL;
  if (!url) return null;

  try {
    const res = await fetch(url, {
      next: { revalidate: 3600 },
    });
    if (!res.ok) return null;
    const json: unknown = await res.json();
    return isAiActivityPayload(json) ? json : null;
  } catch {
    return null;
  }
}

import fallbackPayload from "@/data/ai-activity.fallback.json";
import {
  AI_ACTIVITY_TIMEZONE,
  type AiActivityPayload,
  isAiActivityPayload,
  projectTodayTokens,
} from "@/lib/ai-activity-payload";
import { fetchPublishedAiActivityPayload } from "@/lib/ai-activity-store";

export type DailyTokens = {
  date: string;
  tokens: number;
};

export type Intensity = 0 | 1 | 2 | 3 | 4;

export type ActivityDay = DailyTokens & {
  intensity: Intensity;
  /** Synthetic “live” projection for the current local day. */
  live?: boolean;
};

export type AiActivity = {
  days: ActivityDay[];
  lifetimeTokens: number;
  /** ISO timestamp of the nightly payload, when known. */
  generatedAt: string | null;
  source: "blob" | "fallback";
};

/**
 * Absolute thresholds (tests / small fixtures).
 * Real volumes use relative scaling in `buildAiActivity`.
 */
export function intensityFromTokens(tokens: number): Intensity {
  if (tokens <= 0) return 0;
  if (tokens <= 5_000) return 1;
  if (tokens <= 20_000) return 2;
  if (tokens <= 50_000) return 3;
  return 4;
}

function relativeIntensity(tokens: number, maxTokens: number): Intensity {
  if (tokens <= 0 || maxTokens <= 0) return 0;
  const ratio = tokens / maxTokens;
  if (ratio <= 0.25) return 1;
  if (ratio <= 0.5) return 2;
  if (ratio <= 0.75) return 3;
  return 4;
}

export function buildAiActivity(
  series: readonly DailyTokens[],
  options?: { liveDates?: ReadonlySet<string>; generatedAt?: string | null; source?: AiActivity["source"] },
): AiActivity {
  const max = Math.max(0, ...series.map((d) => d.tokens));
  const useRelative = max > 50_000;
  const liveDates = options?.liveDates;

  const days: ActivityDay[] = series.map((day) => ({
    ...day,
    intensity: useRelative
      ? relativeIntensity(day.tokens, max)
      : intensityFromTokens(day.tokens),
    live: liveDates?.has(day.date) || undefined,
  }));

  const lifetimeTokens = series.reduce((sum, day) => sum + day.tokens, 0);

  return {
    days,
    lifetimeTokens,
    generatedAt: options?.generatedAt ?? null,
    source: options?.source ?? "fallback",
  };
}

function formatDateUTC(date: Date): string {
  const y = date.getUTCFullYear();
  const m = String(date.getUTCMonth() + 1).padStart(2, "0");
  const d = String(date.getUTCDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

/**
 * Deterministic fixture year ending on the given end date (UTC).
 * Used only when no published/fallback payload is available.
 */
export function createFixtureSeries(endDate = new Date("2026-07-17")): DailyTokens[] {
  const end = new Date(
    Date.UTC(endDate.getUTCFullYear(), endDate.getUTCMonth(), endDate.getUTCDate()),
  );
  const start = new Date(end);
  start.setUTCDate(start.getUTCDate() - 364);

  const series: DailyTokens[] = [];
  for (
    let cursor = new Date(start);
    cursor.getTime() <= end.getTime();
    cursor.setUTCDate(cursor.getUTCDate() + 1)
  ) {
    const dayOfYear = Math.floor(
      (cursor.getTime() - Date.UTC(cursor.getUTCFullYear(), 0, 0)) / 86_400_000,
    );
    const weekday = cursor.getUTCDay();
    let tokens = 0;
    if (weekday !== 0 && weekday !== 6) {
      const wave = (Math.sin(dayOfYear / 11) + 1) / 2;
      const burst = dayOfYear % 17 === 0 ? 2.4 : 1;
      tokens = Math.round((800 + wave * 42_000) * burst);
    } else if (dayOfYear % 9 === 0) {
      tokens = 2_400;
    }
    series.push({ date: formatDateUTC(cursor), tokens });
  }
  return series;
}

export const AI_ACTIVITY_FIXTURE = createFixtureSeries();

function payloadFromFallback(): AiActivityPayload {
  if (isAiActivityPayload(fallbackPayload)) return fallbackPayload;
  return {
    version: 1,
    generatedAt: new Date(0).toISOString(),
    timezone: AI_ACTIVITY_TIMEZONE,
    days: AI_ACTIVITY_FIXTURE,
    lifetimeTokens: AI_ACTIVITY_FIXTURE.reduce((s, d) => s + d.tokens, 0),
  };
}

export function materializeAiActivity(
  payload: AiActivityPayload,
  now = new Date(),
  source: AiActivity["source"] = "fallback",
): AiActivity {
  const timeZone = payload.timezone || AI_ACTIVITY_TIMEZONE;
  const history = [...payload.days].sort((a, b) => a.date.localeCompare(b.date));
  const projection = projectTodayTokens(history, now, timeZone);

  const withoutToday = history.filter((d) => d.date < projection.date);
  const series: DailyTokens[] = [
    ...withoutToday,
    { date: projection.date, tokens: projection.tokens },
  ];

  // Keep ~one year of cells for the heatmap.
  const trimmed = series.slice(-365);

  return buildAiActivity(trimmed, {
    liveDates: new Set([projection.date]),
    generatedAt: payload.generatedAt,
    source,
  });
}

export async function getAiActivity(now = new Date()): Promise<AiActivity> {
  const published = await fetchPublishedAiActivityPayload();
  if (published) {
    return materializeAiActivity(published, now, "blob");
  }
  return materializeAiActivity(payloadFromFallback(), now, "fallback");
}

export function formatTokenCount(tokens: number): string {
  return new Intl.NumberFormat("en-US").format(tokens);
}

/** Live counter: start this fraction below the target. */
export const LIVE_COUNT_START_RATIO = 0.8;
/** Live counter: seconds to ease from start → target. */
export const LIVE_COUNT_DURATION_MS = 90_000;

import { timingSafeEqual } from "node:crypto";
import { NextResponse } from "next/server";
import {
  type AiActivityPayload,
  isAiActivityPayload,
} from "@/lib/ai-activity-payload";
import { publishAiActivityPayload } from "@/lib/ai-activity-store";

export const runtime = "nodejs";

function secretsEqual(a: string, b: string): boolean {
  const left = Buffer.from(a);
  const right = Buffer.from(b);
  if (left.length !== right.length) return false;
  return timingSafeEqual(left, right);
}

function authorize(req: Request): boolean {
  const expected = process.env.AI_ACTIVITY_INGEST_SECRET;
  if (!expected) return false;
  const header = req.headers.get("authorization");
  if (!header?.startsWith("Bearer ")) return false;
  return secretsEqual(header.slice("Bearer ".length), expected);
}

export async function POST(req: Request) {
  if (!authorize(req)) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  let body: unknown;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }

  if (!isAiActivityPayload(body)) {
    return NextResponse.json({ error: "Invalid payload" }, { status: 400 });
  }

  const payload = body as AiActivityPayload;

  try {
    const { url } = await publishAiActivityPayload(payload);
    return NextResponse.json({
      ok: true,
      url,
      days: payload.days.length,
      lifetimeTokens: payload.lifetimeTokens,
      generatedAt: payload.generatedAt,
    });
  } catch (error) {
    console.error("AI Activity ingest failed", error);
    return NextResponse.json(
      { error: "Publish failed" },
      { status: 500 },
    );
  }
}

